package com.zeahbloodrunetracker;

import java.time.Duration;
import java.time.Instant;

class ZeahBloodRuneSession
{
	private int bloodRunes;
	private int crafts;
	private Instant startTime;
	private Instant lastCraftTime;

	void recordCraft(int amount, Instant now)
	{
		if (amount <= 0)
		{
			return;
		}

		if (startTime == null)
		{
			startTime = now;
		}

		bloodRunes += amount;
		crafts++;
		lastCraftTime = now;
	}

	void reset()
	{
		bloodRunes = 0;
		crafts = 0;
		startTime = null;
		lastCraftTime = null;
	}

	boolean isActive()
	{
		return lastCraftTime != null;
	}

	boolean hasRate()
	{
		return crafts >= 2;
	}

	boolean hasTimedOut(Instant now, Duration timeout)
	{
		return lastCraftTime != null && Duration.between(lastCraftTime, now).compareTo(timeout) >= 0;
	}

	int getBloodRunes()
	{
		return bloodRunes;
	}

	int getBloodRunesPerHour(Instant now)
	{
		if (!hasRate() || startTime == null)
		{
			return 0;
		}

		long elapsedMillis = Math.max(1L, Duration.between(startTime, now).toMillis());
		return (int) Math.round(bloodRunes * 3_600_000.0 / elapsedMillis);
	}
}

package com.zeahbloodrunetracker;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Units;

@ConfigGroup("zeahbloodrunetracker")
public interface ZeahBloodRuneTrackerConfig extends Config
{
	@ConfigSection(
		name = "Display",
		description = "Choose which statistics are shown on the overlay",
		position = 0
	)
	String displaySection = "display";

	@ConfigItem(
		position = 0,
		keyName = "showBloodRunes",
		name = "Blood runes",
		description = "Show the number of blood runes crafted",
		section = displaySection
	)
	default boolean showBloodRunes()
	{
		return true;
	}

	@ConfigItem(
		position = 1,
		keyName = "showBloodRunesPerHour",
		name = "Bloods/hr",
		description = "Show the estimated blood runes crafted per hour",
		section = displaySection
	)
	default boolean showBloodRunesPerHour()
	{
		return true;
	}

	@ConfigItem(
		position = 2,
		keyName = "showRuneValue",
		name = "Rune value",
		description = "Show the current GE price of one blood rune",
		section = displaySection
	)
	default boolean showRuneValue()
	{
		return true;
	}

	@ConfigItem(
		position = 3,
		keyName = "showMoneyMade",
		name = "Money made",
		description = "Show the GE value of the blood runes crafted",
		section = displaySection
	)
	default boolean showMoneyMade()
	{
		return true;
	}

	@ConfigItem(
		position = 4,
		keyName = "showMoneyPerHour",
		name = "Money/hr",
		description = "Show the estimated GE value of blood runes crafted per hour",
		section = displaySection
	)
	default boolean showMoneyPerHour()
	{
		return true;
	}

	@ConfigItem(
		position = 1,
		keyName = "statTimeout",
		name = "Reset stats",
		description = "The time until the blood runecrafting session is reset"
	)
	@Units(Units.MINUTES)
	default int statTimeout()
	{
		return 5;
	}
}

package com.zeahbloodrunetracker;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.text.NumberFormat;
import java.time.Duration;
import java.time.Instant;
import java.util.Locale;
import javax.inject.Inject;
import net.runelite.api.Client;
import static net.runelite.api.MenuAction.RUNELITE_OVERLAY;
import static net.runelite.api.MenuAction.RUNELITE_OVERLAY_CONFIG;
import net.runelite.api.Player;
import net.runelite.api.gameval.AnimationID;
import static net.runelite.client.ui.overlay.OverlayManager.OPTION_CONFIGURE;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

class ZeahBloodRuneTrackerOverlay extends OverlayPanel
{
	private static final String OVERLAY_NAME = "Zeah blood runes";
	private static final Duration RATE_REFRESH_INTERVAL = Duration.ofSeconds(10);

	private final Client client;
	private final ZeahBloodRuneTrackerPlugin plugin;
	private final ZeahBloodRuneTrackerConfig config;
	private int displayedBloodRunesPerHour;
	private int bloodRunesAtLastRateRefresh = -1;
	private Instant lastRateRefresh;

	@Inject
	ZeahBloodRuneTrackerOverlay(Client client, ZeahBloodRuneTrackerPlugin plugin,
		ZeahBloodRuneTrackerConfig config)
	{
		super(plugin);
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		addMenuEntry(RUNELITE_OVERLAY_CONFIG, OPTION_CONFIGURE, OVERLAY_NAME);
		addMenuEntry(RUNELITE_OVERLAY, "Reset", OVERLAY_NAME, event -> plugin.reset());
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		ZeahBloodRuneSession session = plugin.getSession();
		if (!session.isActive())
		{
			resetRateDisplay();
			return null;
		}

		Player player = client.getLocalPlayer();
		boolean runecrafting = player != null
			&& (player.getAnimation() == AnimationID.RUNECRAFTING
				|| player.getAnimation() == AnimationID.HUMAN_RUNECRAFT);

		panelComponent.getChildren().add(TitleComponent.builder()
			.text(runecrafting ? "Runecrafting" : "NOT runecrafting")
			.color(runecrafting ? Color.GREEN : Color.RED)
			.build());

		if (config.showBloodRunes())
		{
			addLine("Blood runes:", session.getBloodRunes());
		}

		Instant now = plugin.now();
		refreshRateDisplay(session, now);
		int bloodRunesPerHour = displayedBloodRunesPerHour;
		if (config.showBloodRunesPerHour() && session.hasRate())
		{
			addLine("Bloods/hr:", bloodRunesPerHour);
		}

		int bloodRunePrice = plugin.getBloodRunePrice();
		if (config.showRuneValue())
		{
			addLine("GE price:", bloodRunePrice);
		}

		if (config.showMoneyMade())
		{
			addLine("Money made:", (long) session.getBloodRunes() * bloodRunePrice);
		}

		if (config.showMoneyPerHour() && session.hasRate())
		{
			addLine("Money/hr:", (long) bloodRunesPerHour * bloodRunePrice);
		}

		return super.render(graphics);
	}

	private void refreshRateDisplay(ZeahBloodRuneSession session, Instant now)
	{
		boolean newCraft = session.getBloodRunes() != bloodRunesAtLastRateRefresh;
		boolean refreshDue = lastRateRefresh == null
			|| Duration.between(lastRateRefresh, now).compareTo(RATE_REFRESH_INTERVAL) >= 0;

		if (newCraft || refreshDue)
		{
			displayedBloodRunesPerHour = session.getBloodRunesPerHour(now);
			bloodRunesAtLastRateRefresh = session.getBloodRunes();
			lastRateRefresh = now;
		}
	}

	private void resetRateDisplay()
	{
		displayedBloodRunesPerHour = 0;
		bloodRunesAtLastRateRefresh = -1;
		lastRateRefresh = null;
	}

	private void addLine(String label, long value)
	{
		panelComponent.getChildren().add(LineComponent.builder()
			.left(label)
			.right(NumberFormat.getIntegerInstance(Locale.US).format(value))
			.build());
	}

}

package com.zeahbloodrunetracker;

import com.google.inject.Provides;
import java.time.Duration;
import java.time.Instant;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.StatChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "Zeah Blood Rune Tracker",
	description = "Tracks blood runes crafted with dark essence fragments on Zeah",
	tags = {"arceuus", "blood", "runecrafting", "skilling", "zeah"}
)
@Singleton
public class ZeahBloodRuneTrackerPlugin extends Plugin
{
	private static final Duration PRICE_REFRESH_INTERVAL = Duration.ofMinutes(5);
	private static final int CRAFT_EVENT_GRACE_TICKS = 3;
	private static final int ALTAR_CLICK_GRACE_TICKS = 8;

	private final ZeahBloodRuneSession session = new ZeahBloodRuneSession();

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ZeahBloodRuneTrackerOverlay overlay;

	@Inject
	private ZeahBloodRuneTrackerConfig config;

	@Inject
	private ItemManager itemManager;

	private int previousBloodRunes;
	private int previousRunecraftingXp = -1;
	private int pendingBloodRuneIncrease;
	private int pendingBloodRuneTicks;
	private int pendingRunecraftingXpTicks;
	private int pendingAltarClickTicks;
	private boolean inventorySnapshotReady;
	private int bloodRunePrice;
	private Instant lastPriceRefresh;

	@Provides
	ZeahBloodRuneTrackerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ZeahBloodRuneTrackerConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		clientThread.invoke(() ->
		{
			snapshotInventory();
			refreshBloodRunePrice(now());
		});
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		session.reset();
		inventorySnapshotReady = false;
		previousRunecraftingXp = -1;
		clearPendingCraft();
		bloodRunePrice = 0;
		lastPriceRefresh = null;
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (event.getSkill() != Skill.RUNECRAFT)
		{
			return;
		}

		int runecraftingXp = event.getXp();
		if (previousRunecraftingXp >= 0 && runecraftingXp > previousRunecraftingXp)
		{
			if (pendingBloodRuneIncrease > 0 && pendingBloodRuneTicks > 0)
			{
				session.recordCraft(pendingBloodRuneIncrease, now());
				pendingBloodRuneIncrease = 0;
				pendingBloodRuneTicks = 0;
			}
			else
			{
				pendingRunecraftingXpTicks = CRAFT_EVENT_GRACE_TICKS;
			}
		}
		previousRunecraftingXp = runecraftingXp;
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		String option = event.getMenuOption() == null ? "" : event.getMenuOption();
		String target = event.getMenuTarget() == null ? "" : event.getMenuTarget();

		String lowerOption = option.toLowerCase();
		String lowerTarget = target.toLowerCase();
		if (lowerOption.contains("craft-rune") || lowerOption.contains("craft rune")
			|| lowerTarget.contains("altar"))
		{
			pendingAltarClickTicks = ALTAR_CLICK_GRACE_TICKS;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		Instant now = now();
		processInventoryChanges(now);
		advancePendingCraftWindow();

		if (bloodRunePrice <= 0 || lastPriceRefresh == null
			|| Duration.between(lastPriceRefresh, now).compareTo(PRICE_REFRESH_INTERVAL) >= 0)
		{
			refreshBloodRunePrice(now);
		}

		if (session.hasTimedOut(now, Duration.ofMinutes(config.statTimeout())))
		{
			reset();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState gameState = event.getGameState();
		if (gameState == GameState.LOGIN_SCREEN || gameState == GameState.HOPPING
			|| gameState == GameState.CONNECTION_LOST)
		{
			inventorySnapshotReady = false;
			previousRunecraftingXp = -1;
			clearPendingCraft();
		}
		else if (gameState == GameState.LOGGED_IN)
		{
			snapshotInventory();
		}
	}

	void reset()
	{
		session.reset();
		snapshotInventory();
	}

	ZeahBloodRuneSession getSession()
	{
		return session;
	}

	int getBloodRunePrice()
	{
		return bloodRunePrice;
	}

	Instant now()
	{
		return Instant.now();
	}

	static int getCraftedBloodRuneIncrease(int previousBloodRunes, int bloodRunes,
		boolean recentRunecraftingXp)
	{
		int bloodRuneIncrease = bloodRunes - previousBloodRunes;
		return bloodRuneIncrease > 0 && recentRunecraftingXp
			? bloodRuneIncrease : 0;
	}

	private void snapshotInventory()
	{
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory == null)
		{
			inventorySnapshotReady = false;
			return;
		}

		previousBloodRunes = inventory.count(ItemID.BLOODRUNE);
		previousRunecraftingXp = client.getSkillExperience(Skill.RUNECRAFT);
		inventorySnapshotReady = true;
		clearPendingCraft();
	}

	private void processInventoryChanges(Instant now)
	{
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory == null)
		{
			inventorySnapshotReady = false;
			clearPendingCraft();
			return;
		}

		// count() returns the true integer quantity. The white 100K-style text is
		// only how the game draws the stack and is never read by this plugin.
		int bloodRunes = inventory.count(ItemID.BLOODRUNE);

		if (inventorySnapshotReady && bloodRunes > previousBloodRunes)
		{
			int bloodRuneIncrease = bloodRunes - previousBloodRunes;
			if (pendingRunecraftingXpTicks > 0 || pendingAltarClickTicks > 0)
			{
				session.recordCraft(bloodRuneIncrease, now);
				pendingRunecraftingXpTicks = 0;
				pendingAltarClickTicks = 0;
			}
			else
			{
				// StatChanged and the final inventory state can be delivered on either
				// side of GameTick. Hold the increase briefly so the XP event can pair
				// with it regardless of delivery order.
				pendingBloodRuneIncrease = bloodRuneIncrease;
				pendingBloodRuneTicks = CRAFT_EVENT_GRACE_TICKS;
			}
		}

		previousBloodRunes = bloodRunes;
		inventorySnapshotReady = true;
	}

	private void advancePendingCraftWindow()
	{
		if (pendingBloodRuneTicks > 0 && --pendingBloodRuneTicks == 0)
		{
			pendingBloodRuneIncrease = 0;
		}

		if (pendingRunecraftingXpTicks > 0)
		{
			pendingRunecraftingXpTicks--;
		}

		if (pendingAltarClickTicks > 0)
		{
			pendingAltarClickTicks--;
		}
	}

	private void clearPendingCraft()
	{
		pendingBloodRuneIncrease = 0;
		pendingBloodRuneTicks = 0;
		pendingRunecraftingXpTicks = 0;
		pendingAltarClickTicks = 0;
	}

	private void refreshBloodRunePrice(Instant now)
	{
		bloodRunePrice = itemManager.getItemPrice(ItemID.BLOODRUNE);
		lastPriceRefresh = now;
	}

}

package com.zeahbloodrunetracker;

import java.time.Duration;
import java.time.Instant;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class ZeahBloodRuneSessionTest
{
	@Test
	public void tracksBloodRunesAndHourlyRate()
	{
		ZeahBloodRuneSession session = new ZeahBloodRuneSession();
		Instant start = Instant.parse("2026-01-01T00:00:00Z");
		session.recordCraft(50, start);
		session.recordCraft(50, start.plusSeconds(60));

		assertEquals(100, session.getBloodRunes());
		assertEquals(6000, session.getBloodRunesPerHour(start.plusSeconds(60)));
		assertTrue(session.hasRate());
	}

	@Test
	public void timesOutFromLastCraft()
	{
		ZeahBloodRuneSession session = new ZeahBloodRuneSession();
		Instant start = Instant.parse("2026-01-01T00:00:00Z");
		session.recordCraft(50, start);

		assertFalse(session.hasTimedOut(start.plusSeconds(299), Duration.ofMinutes(5)));
		assertTrue(session.hasTimedOut(start.plusSeconds(300), Duration.ofMinutes(5)));
	}

	@Test
	public void resetClearsTheSession()
	{
		ZeahBloodRuneSession session = new ZeahBloodRuneSession();
		session.recordCraft(50, Instant.now());
		session.reset();

		assertFalse(session.isActive());
		assertEquals(0, session.getBloodRunes());
	}

	@Test
	public void onlyCountsBloodsWhenRunecraftingXpIsGained()
	{
		assertEquals(52, ZeahBloodRuneTrackerPlugin.getCraftedBloodRuneIncrease(100, 152, true));
		assertEquals(220, ZeahBloodRuneTrackerPlugin.getCraftedBloodRuneIncrease(105_631, 105_851, true));
		assertEquals(0, ZeahBloodRuneTrackerPlugin.getCraftedBloodRuneIncrease(105_631, 105_851, false));
		assertEquals(0, ZeahBloodRuneTrackerPlugin.getCraftedBloodRuneIncrease(100, 100, true));
	}

	@Test
	public void doesNotCountOrdinaryInventoryIncreases()
	{
		assertEquals(0, ZeahBloodRuneTrackerPlugin.getCraftedBloodRuneIncrease(105_000, 110_000, false));
	}
}

package com.zeahbloodrunetracker;

